"""Reference pages: one per header (docs/api/vmafx/<header>.md) and their index
(docs/api/vmafx/reference.md). The hand-written overview is docs/api/vmafx/index.md."""

from __future__ import annotations

from . import ctext
from .headers import HeaderPlan, plan
from .layout import layouts
from .model import Api, Compat, Deprecation, Struct, version_text

DOCS_DIR = "docs/api/vmafx/"
GENERATED = (
    "<!-- markdownlint-disable MD013 -->\n"
    "<!-- GENERATED by scripts/codegen/vmafx-api.py from core/api/vmafx.toml (ADR-1852). "
    "Do not edit. -->\n"
)


def page_path(plan_item: HeaderPlan) -> str:
    return f"{DOCS_DIR}{plan_item.header.stem}.md"


def _cell(text: str) -> str:
    return text.replace("|", "\\|")


def _life(since: tuple[int, int], dep: Deprecation | None) -> str:
    text = version_text(since)
    if dep is not None:
        text += f"; deprecated {ctext.deprecation_note(dep)}"
    return text


def _functions(api: Api, item: HeaderPlan) -> list[str]:
    if not item.functions:
        return []
    out = ["## Functions", "", "| Function | Since | Description |", "| --- | --- | --- |"]
    out += [
        f"| `{fn.name}` | {_life(fn.since, fn.deprecated)} | {_cell(fn.doc)} |"
        for fn in item.functions
    ]
    out += ["", "```c"]
    out += [ctext.declaration(api, fn, api.export_macro) for fn in item.functions]
    return [*out, "```", ""]


def _struct(api: Api, item: Struct) -> list[str]:
    lay = layouts(api)[item.name]
    head = f"{item.doc} Size {lay.size} bytes, alignment {lay.align}. Since {_life(item.since, item.deprecated)}."
    out = [f"### `{item.name}`", "", head, ""]
    out += [
        "| Field | C declaration | Offset | Since | Description |",
        "| --- | --- | --- | --- | --- |",
    ]
    for fld, place in zip(item.fields, lay.fields, strict=True):
        decl = ctext.field_decl(api, fld).rstrip(";")
        note = (
            fld.doc
            + (f" Values: `{fld.enum}`." if fld.enum else "")
            + (f" Bits: `{fld.flags}`." if fld.flags else "")
        )
        out.append(
            f"| `{fld.name}` | `{decl}` | {place.offset} | {_life(fld.since, fld.deprecated)} | {_cell(note.strip())} |"
        )
    if item.sized:
        out += ["", f"Initialise with `{item.init_macro}`."]
    return [*out, ""]


def _handles(api: Api, item: HeaderPlan) -> list[str]:
    if not (item.handles or item.callbacks):
        return []
    out = ["## Handles and callbacks", "", "| Type | Since | Description |", "| --- | --- | --- |"]
    for handle in item.handles:
        doc = f"{_cell(handle.doc)} Released by `{handle.release}`."
        out.append(f"| `{handle.name}` | {_life(handle.since, handle.deprecated)} | {doc} |")
    for callback in item.callbacks:
        life = _life(callback.since, callback.deprecated)
        out.append(f"| `{callback.name}` | {life} | {_cell(callback.doc)} |")
    out.append("")
    if item.callbacks:
        typedefs = [ctext.callback_typedef(api, c) for c in item.callbacks]
        out += ["```c", *typedefs, "```", ""]
    return out


def _types(api: Api, item: HeaderPlan) -> list[str]:
    out = _handles(api, item)
    if item.structs:
        out += ["## Structs", ""]
        for struct in item.structs:
            out += _struct(api, struct)
    return out


def _constants(api: Api, item: HeaderPlan) -> list[str]:
    out: list[str] = []
    if item.header.path == api.base_header:
        out += [
            "## Status codes",
            "",
            "| Code | Value | libvmaf errno | Since | Meaning |",
            "| --- | --- | --- | --- | --- |",
        ]
        for status in api.statuses:
            errno = "0" if status.errno == "0" else f"-{status.errno}"
            out.append(
                f"| `{status.name}` | {status.value} | `{errno}` | {_life(status.since, status.deprecated)} | {_cell(status.doc)} |"
            )
        out.append("")
    for enum in item.enums:
        out += [
            f"## `{enum.name}`",
            "",
            f"{enum.doc} Since {_life(enum.since, enum.deprecated)}.",
            "",
        ]
        out += ["| Constant | Value | Since |", "| --- | --- | --- |"]
        out += [f"| `{v.name}` | {v.value} | {_life(v.since, v.deprecated)} |" for v in enum.values]
        out.append("")
    for flags in item.flags:
        out += [
            f"## `{flags.name}`",
            "",
            f"{flags.doc} Bits of a `{flags.type}` field. Since {_life(flags.since, flags.deprecated)}.",
            "",
        ]
        out += ["| Constant | Bit | Since | Meaning |", "| --- | --- | --- | --- |"]
        out += [
            f"| `{b.name}` | {b.bit} | {_life(b.since, b.deprecated)} | {_cell(b.doc)} |"
            for b in flags.bits
        ]
        out.append("")
    return out


def _includes_line(item: HeaderPlan) -> list[str]:
    if item.header.group == "umbrella":
        listed = ", ".join(
            f"[`{p}`]({p.rsplit('/', 1)[-1].removesuffix('.h')}.md)" for p in item.includes
        )
        return [f"Includes every core header: {listed}.", ""]
    note = (
        " Optional: the umbrella header does not include it."
        if item.header.group == "optional"
        else ""
    )
    return [f"`#include <{item.header.path}>`.{note}", ""]


def header_page(api: Api, item: HeaderPlan) -> str:
    lines = [GENERATED + f"# `{item.header.path}`", "", item.header.brief, ""]
    lines += _includes_line(item)
    body = _constants(api, item) + _types(api, item) + _functions(api, item)
    if not body and item.header.group != "umbrella":
        body = ["No declarations yet: a later RC4 work package fills this header.", ""]
    lines += body
    lines += ["Back to the [reference index](reference.md).", ""]
    return "\n".join(lines).rstrip("\n") + "\n"


def _compat(api: Api) -> list[str]:
    if not api.compats:
        return []
    return [
        "## libvmaf functions",
        "",
        f"The {len(api.compats)} functions of the libvmaf headers and the VMAFx calls each one",
        "is written on: [libvmaf migration table](compat.md).",
        "",
    ]


COMPAT_KIND_TEXT = {
    "shim": "generated shim",
    "glue": "generated glue",
    "manual": "hand-written",
    "engine": "engine (exception)",
}


def _compat_where(item: Compat) -> str:
    """Which library defines the function in which build."""
    if item.kind == "engine":
        return f"libvmafx.so.1 in builds with {item.engine_with}; until {item.until}"
    if item.engine_with:
        return (
            f"libvmaf.so.3 in builds without {item.engine_with}; with it, libvmafx.so.1"
            f" until {item.until}"
        )
    if item.when:
        return f"libvmaf.so.3 in builds with {item.when}"
    return "libvmaf.so.3"


def _compat_row(item: Compat) -> str:
    calls = ", ".join(f"`{c}`" for c in item.calls) or f"`{item.target}`"
    note = f" {item.note}." if item.note else ""
    return (
        f"| `{item.name}` | `{item.header}` | {calls} | {COMPAT_KIND_TEXT[item.kind]} |"
        f" {_cell(_compat_where(item))}.{_cell(note)} |"
    )


def compat_text(api: Api) -> str:
    """The migration table: every libvmaf function and what it is built on."""
    counts = {kind: sum(c.kind == kind for c in api.compats) for kind in COMPAT_KIND_TEXT}
    summary = ", ".join(f"{n} {COMPAT_KIND_TEXT[k]}" for k, n in counts.items() if n)
    lines = [
        GENERATED + "# libvmaf migration table (generated)",
        "",
        f"Every function of the libvmaf headers ({len(api.compats)}: {summary}) and the VMAFx",
        "calls it is written on. `libvmaf.so.3` defines them on the exported `vmafx_*`",
        "functions of `libvmafx.so.1` and links nothing else; a function marked engine",
        "(exception) keeps the engine's own definition in `libvmafx.so.1` while its backend",
        "is built, until the lane named in the last column lands. The",
        "[VMAFx API page](index.md#migrating-from-libvmafh) explains the layout, the",
        "deprecation warnings and the few deliberate differences.",
        "",
        "| libvmaf function | Header | VMAFx calls | Kind | Library |",
        "| --- | --- | --- | --- | --- |",
        *[_compat_row(c) for c in api.compats],
        "",
        "Back to the [reference index](reference.md).",
    ]
    return "\n".join(lines) + "\n"


def index_text(api: Api) -> str:
    rows = ["| Header | Group | Contents |", "| --- | --- | --- |"]
    for item in plan(api):
        stem = item.header.stem
        rows.append(
            f"| [`{item.header.path}`]({stem}.md) | {item.header.group} | {_cell(item.header.brief)} |"
        )
    lines = [
        GENERATED + "# VMAFx C API reference (generated)",
        "",
        f"ABI version {version_text(api.abi_version)}. These pages are generated from",
        "[`core/api/vmafx.toml`](../../../core/api/vmafx.toml); the overview is",
        "[the VMAFx API page](index.md). Include `<vmafx/vmafx.h>` for every core header,",
        "or a single header for what it declares; each includes what its declarations use.",
        "",
        *rows,
        "",
        *_compat(api),
    ]
    return "\n".join(lines).rstrip("\n") + "\n"


def pages(api: Api) -> list[tuple[str, str]]:
    """(path, text) of every reference page, the index first."""
    out = [(f"{DOCS_DIR}reference.md", index_text(api))]
    out += [(page_path(item), header_page(api, item)) for item in plan(api)]
    if api.compats:
        out.append((f"{DOCS_DIR}compat.md", compat_text(api)))
    return out
